"""Deterministic make.fun output writer for news-image-20261125."""
import base64
import os

# Embedded poster bytes keep runtime generation independent of repo files.


PNG_B64 = """"""


def main():
    output_dir = os.environ.get("MAKEFUN_OUTPUT_DIR") or os.path.dirname(os.path.abspath(__file__))
    os.makedirs(output_dir, exist_ok=True)
    with open(os.path.join(output_dir, "entry.png"), "wb") as output:
        output.write(base64.b64decode(PNG_B64))


if __name__ == "__main__":
    main()
